## Modal backend kód (glm46_modal_app.py)

A backend Modal alkalmazás egy CUDA-alapú image-ben futtatja a vLLM-et, bfloat16 formátummal és 200000 tokenes max_model_len beállítással, hogy kihasználja a GLM-4.6 200K-es kontextusablakát.  A `@modal.fastapi_endpoint(method="POST")` dekorátor HTTP POST végponttá teszi a függvényt, amely JSON body-ban kapja meg a promptot, hőmérsékletet és max_tokens értéket, majd a kimenetet `response` mezőben adja vissza.[2][8][7][9][1]

```python
import modal
from typing import Any, Dict

app = modal.App("glm46-b200-vllm-api")

vllm_image = (
    modal.Image.from_registry("nvidia/cuda:12.8.0-devel-ubuntu22.04", add_python="3.12")
    .entrypoint([])
    .pip_install(
        "vllm==0.10.2",
        "huggingface_hub[hf_transfer]==0.35.0",
        "flashinfer-python==0.3.1",
        "torch==2.8.0",
        "fastapi==0.115.5",
        "pydantic==2.10.3",
        "uvicorn==0.32.1"
    )
    .env(
        {
            "HF_HUB_ENABLE_HF_TRANSFER": "1"
        }
    )
)

MODEL_NAME = "zai-org/GLM-4.6"
MAX_CONTEXT_TOKENS = 200000
DEFAULT_MAX_OUTPUT_TOKENS = 120000
DEFAULT_TEMPERATURE = 0.7

llm_instance = None

def load_llm_if_needed() -> None:
    global llm_instance
    if llm_instance is None:
        from vllm import LLM
        llm_instance = LLM(
            model=MODEL_NAME,
            dtype="bfloat16",
            max_model_len=MAX_CONTEXT_TOKENS,
            tensor_parallel_size=1,
            gpu_memory_utilization=0.95
        )

@app.function(
    image=vllm_image,
    gpu="B200",
    timeout=3600,
    container_idle_timeout=600
)
@modal.fastapi_endpoint(method="POST", docs=False)
def generate(payload: Dict[str, Any]) -> Dict[str, Any]:
    from vllm import SamplingParams
    prompt_value = payload.get("prompt", "")
    if isinstance(prompt_value, str):
        prompt_text = prompt_value
    else:
        prompt_text = str(prompt_value)
    temperature_value = payload.get("temperature", DEFAULT_TEMPERATURE)
    max_tokens_value = payload.get("max_tokens", DEFAULT_MAX_OUTPUT_TOKENS)
    try:
        temperature = float(temperature_value)
    except (TypeError, ValueError):
        temperature = DEFAULT_TEMPERATURE
    try:
        max_tokens = int(max_tokens_value)
    except (TypeError, ValueError):
        max_tokens = DEFAULT_MAX_OUTPUT_TOKENS
    if max_tokens <= 0:
        max_tokens = DEFAULT_MAX_OUTPUT_TOKENS
    if max_tokens > DEFAULT_MAX_OUTPUT_TOKENS:
        max_tokens = DEFAULT_MAX_OUTPUT_TOKENS
    if temperature < 0.0:
        temperature = DEFAULT_TEMPERATURE
    load_llm_if_needed()
    sampling_params = SamplingParams(
        temperature=temperature,
        top_p=0.9,
        max_tokens=max_tokens,
        stop=["<|endoftext|>", "<|user|>"]
    )
    outputs = llm_instance.generate([prompt_text], sampling_params)
    text_output = outputs[0].outputs[0].text
    return {
        "response": text_output
    }
