## Replit backend kód (app.py)

A Replit oldali Flask szerver egy vékony proxy réteg, amely a `/api/chat` végponton érkező JSON kéréseket továbbítja a Modal HTTPS endpoint felé, és a választ változtatás nélkül visszaadja a frontendnek.  A Modal endpoint URL-jét és opcionális auth tokent környezeti változókból olvassa, így a titkok nem kerülnek bele a kódba, ami gyakorlatnak megfelelő produkciós megoldás.[7][9]

```python
from flask import Flask, request, jsonify, render_template
import requests
import os

app = Flask(__name__)

MODAL_ENDPOINT_URL = os.environ.get("MODAL_ENDPOINT_URL")
MODAL_AUTH_TOKEN = os.environ.get("MODAL_AUTH_TOKEN")

def call_modal_backend(prompt: str, temperature: float, max_tokens: int) -> dict:
    if MODAL_ENDPOINT_URL is None:
        return {
            "error": "MODAL_ENDPOINT_URL environment variable is not set"
        }
    headers = {
        "Content-Type": "application/json"
    }
    if MODAL_AUTH_TOKEN is not None:
        headers["Authorization"] = "Bearer " + MODAL_AUTH_TOKEN
    payload = {
        "prompt": prompt,
        "temperature": temperature,
        "max_tokens": max_tokens
    }
    response = requests.post(
        MODAL_ENDPOINT_URL,
        json=payload,
        headers=headers,
        timeout=300
    )
    try:
        data = response.json()
    except ValueError:
        data = {
            "error": "Invalid JSON response from Modal backend"
        }
    if response.ok:
        return data
    return {
        "error": data.get("detail", "Modal backend returned an error")
    }

@app.route("/", methods=["GET"])
def index() -> str:
    return render_template("index.html")

@app.route("/api/chat", methods=["POST"])
def chat() -> tuple:
    json_data = request.get_json(silent=True)
    if json_data is None:
        return jsonify({"error": "Request body must be JSON"}), 400
    prompt_value = json_data.get("prompt", "")
    if isinstance(prompt_value, str):
        prompt_text = prompt_value
    else:
        prompt_text = str(prompt_value)
    temperature_value = json_data.get("temperature", 0.7)
    max_tokens_value = json_data.get("max_tokens", 120000)
    try:
        temperature = float(temperature_value)
    except (TypeError, ValueError):
        temperature = 0.7
    try:
        max_tokens = int(max_tokens_value)
    except (TypeError, ValueError):
        max_tokens = 120000
    if max_tokens <= 0:
        max_tokens = 120000
    if max_tokens > 120000:
        max_tokens = 120000
    result = call_modal_backend(prompt_text, temperature, max_tokens)
    status_code = 200
    if "error" in result:
        status_code = 502
    return jsonify(result), status_code

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
```

